PERMTEST = ("import math, random\n\n"
            "rng = random.Random(6)\n"
            "old = [62, 70, 58, 66, 71, 64, 59, 68, 63, 67, 60, 65]\n"
            "new = [68, 74, 63, 70, 77, 66, 65, 72, 69, 71, 64, 73]\n"
            "mean = lambda xs: sum(xs) / len(xs)\n"
            "observed = mean(new) - mean(old)\n\n"
            "pooled = old + new\n"
            "R, extreme = 500, 0\n"
            "for _ in range(R):\n"
            "    rng.shuffle(pooled)\n"
            "    d = mean(pooled[len(old):]) - mean(pooled[:len(old)])\n"
            "    extreme += abs(d) >= abs(observed)\n"
            "p = (extreme + 1) / (R + 1)\n"
            "print(f'бақыланған айырма: {observed:.2f} ұпай, ауыстыру тестінің p-мәні: {p:.4f}')\n\n"
            "# Көп салыстыру: 20 «әдіс» салыстырылды, ешқайсысының шын әсері ЖОҚ (жылдамдық үшін z-тест)\n"
            "false_hits, smallest = 0, 1.0\n"
            "for k in range(20):\n"
            "    a = [rng.gauss(65, 4) for _ in range(12)]\n"
            "    b = [rng.gauss(65, 4) for _ in range(12)]\n"
            "    z = (mean(b) - mean(a)) / math.sqrt(2 * 16 / 12)\n"
            "    pk = math.erfc(abs(z) / math.sqrt(2))\n"
            "    false_hits += pk < 0.05\n"
            "    smallest = min(smallest, pk)\n"
            "print(f'ең кіші p = {smallest:.4f}; Бонферрони шегінен (0.0025) өткені: {smallest <= 0.0025}')\n"
            "print(f'20 бос салыстырудан «маңызды» шыққаны: {false_hits} (күтілетін 20 · 0.05 = 1); Бонферрони шегі 0.05/20 = 0.0025')")

