# ---------------------------------------------------------------- 7-сабақ
PPV = ("def ppv(prior, power, alpha):\n"
       "    \"\"\"«маңызды» нәтиженің шынымен шын болу ықтималдығы (Байес)\"\"\"\n"
       "    return power * prior / (power * prior + alpha * (1 - prior))\n\n"
       "fields = {\n"
       "    'жақсы дәлелденген тақырып':         (0.5, 0.8),\n"
       "    'жаңа, батыл гипотезалар':           (0.1, 0.8),\n"
       "    'батыл гипотезалар, аз үлгі':        (0.1, 0.3),\n"
       "    'батыл, аз үлгі, көп нұсқа (p-hacking)': (0.1, 0.3),\n"
       "}\n"
       "for name, (prior, power) in fields.items():\n"
       "    alpha = 0.05 if 'p-hacking' not in name else 1 - 0.95 ** 5     # 5 талдау нұсқасынан «ең жақсысын» таңдау\n"
       "    print(f'{name:40} алдын ала {prior:.1f}, қуат {power:.1f}, тиімді α {alpha:.3f} -> маңызды нәтиженің шын болу ықтималдығы {ppv(prior, power, alpha):.2f}')")

