INFL = ("import math, random\n\n"
        "rng = random.Random(8)\n"
        "TRUE = 1.0            # шын әсер (ұпай)\n"
        "SE = 1.5              # әр шағын зерттеудің стандарт қатесі\n"
        "studies = [rng.gauss(TRUE, SE) for _ in range(4000)]\n"
        "published = [d for d in studies if d / SE > 1.96]            # тек «маңыздылары» жарияланады\n"
        "print(f'барлық зерттеудің орташа бағасы: {sum(studies) / len(studies):.2f} (шындық {TRUE})')\n"
        "print(f'жарияланғандардың орташасы:     {sum(published) / len(published):.2f}  ({len(published)} зерттеу, {len(published) / len(studies):.0%})')\n"
        "print(f'асыру коэффициенті: {sum(published) / len(published) / TRUE:.1f} есе')\n\n"
        "# Нәтижені асыра айтпай тұжырымдау\n"
        "effect, lo, hi = 2.9, 1.2, 4.6\n"
        "print('ЖАМАН: «жаңа әдіс оқуды күрт жақсартады»')\n"
        "print(f'ЖАҚСЫ: «8-9 сыныптарда бір тоқсанда өсім {effect} ұпай (95% CI [{lo}, {hi}]); басқа сыныптарға жалпылау тексерілмеген»')")

