ETHICS = ("def shingles(text, k=3):\n"
          "    words = text.lower().split()\n"
          "    return {tuple(words[i:i + k]) for i in range(len(words) - k + 1)}\n\n"
          "def jaccard(a, b):\n"
          "    A, B = shingles(a), shingles(b)\n"
          "    return len(A & B) / len(A | B) if A | B else 0.0\n\n"
          "source = 'рандомизация кез келген шатастырушыны күтімде теңестіреді сондықтан эксперимент себептілік туралы тұжырым жасауға мүмкіндік береді'\n"
          "texts = {\n"
          "    'дәйексөзсіз көшірме': 'рандомизация кез келген шатастырушыны күтімде теңестіреді сондықтан эксперимент себептілік туралы тұжырым жасауға мүмкіндік береді',\n"
          "    'сөзбе-сөз емес, бірақ жақын': 'рандомизация кез келген шатастырушыны орта есеппен теңестіреді сондықтан эксперимент себептілік туралы айтуға мүмкіндік береді',\n"
          "    'өз сөзімен түсіндіру': 'топтарға кездейсоқ бөлгенде біз білмейтін факторлар да орта есеппен бірдей болады',\n"
          "}\n"
          "for name, t in texts.items():\n"
          "    print(f'{name:28} ұқсастық {jaccard(source, t):.2f}')\n\n"
          "alpha, k = 0.05, 10\n"
          "print(f'{k} талдау нұсқасынан бірі «маңызды» болу ықтималдығы (әсер жоқ): {1 - (1 - alpha) ** k:.2f}')")

