STUDY = ("import math, random\n\n"
         "# Толық шағын зерттеу: алдын ала тіркелген жоспар -> эксперимент -> талдау -> тұжырым\n"
         "PLAN = {'гипотеза': 'Code X-Ray-мен оқыған топ рекурсия тестінен кемінде 5 ұпай жоғары алады',\n"
         "        'n_әр_топ': 60, 'метрика': 'тест ұпайы (0-100)', 'тест': 'z-тест, α = 0.05', 'seed': 17}\n"
         "rng = random.Random(PLAN['seed'])\n"
         "n = PLAN['n_әр_топ']\n"
         "control = [min(100, max(0, rng.gauss(62, 14))) for _ in range(n)]\n"
         "treated = [min(100, max(0, rng.gauss(68, 14))) for _ in range(n)]\n"
         "mean = lambda xs: sum(xs) / len(xs)\n"
         "eff = mean(treated) - mean(control)\n\n"
         "def var(xs):\n"
         "    m = mean(xs)\n"
         "    return sum((x - m) ** 2 for x in xs) / (len(xs) - 1)\n"
         "se = math.sqrt(var(treated) / n + var(control) / n)   # орташалар айырмасының стандарт қатесі\n"
         "lo, hi = eff - 1.96 * se, eff + 1.96 * se             # 95% интервал (қалыпты жуықтау, 5-сабақ)\n"
         "p = math.erfc(abs(eff / se) / math.sqrt(2))           # екі жақты p-мән (z-тест)\n"
         "print(f'әсер {eff:.1f} ұпай, 95% CI [{lo:.1f}, {hi:.1f}], p = {p:.4f}')\n"
         "supported = lo > 0\n"
         "print('бағыт:', 'сенімді оң' if supported else 'сенімсіз', '| гипотезадағы ≥ 5 ұпай:', 'интервал толық ≥ 5' if lo >= 5 else 'расталмады (интервал 5-тен төмен мәндерді қамтиды)')")

